const replaceHeight = (declaration: string): string => {
    const match = declaration.match(/^(\s*height\s*:\s*)([\s\S]*)$/i);

    if (!match || !/vh/i.test(match[2])) {
        return declaration;
    }

    const important = match[2].match(/\s*!important\s*$/i)?.[0] || '';
    return `${match[1]}auto${important}`;
};

const replaceViewportHeights = (style: string): string => {
    let result = '';
    let start = 0;
    let quote = '';
    let depth = 0;
    let inComment = false;

    for (let index = 0; index < style.length; index++) {
        const character = style[index];
        const next = style[index + 1];

        if (character === ';' && !quote && !inComment && depth === 0) {
            result += replaceHeight(style.slice(start, index));
            result += ';';
            start = index + 1;
        } else if (inComment) {
            if (character === '*' && next === '/') {
                inComment = false;
                index++;
            }
        } else if (quote) {
            if (character === '\\') {
                index++;
            } else if (character === quote) {
                quote = '';
            }
        } else if (character === '/' && next === '*') {
            inComment = true;
            index++;
        } else if (character === '"' || character === "'") {
            quote = character;
        } else if (character === '(') {
            depth++;
        } else if (character === ')' && depth > 0) {
            depth--;
        }
    }

    return result + replaceHeight(style.slice(start));
};

export const transformStyleAttributes = (document: Element): void => {
    const elements = [document, ...document.querySelectorAll('[style]')];

    elements.forEach((element) => {
        const style = element.getAttribute('style');

        if (style === null) {
            return;
        }

        const nextStyle = replaceViewportHeights(style);

        if (nextStyle !== style) {
            element.setAttribute('style', nextStyle);
        }
    });
};
import { MailSettings } from '@proton/shared/lib/interfaces';
import { Attachment } from '@proton/shared/lib/interfaces/mail/Message';
import { transformLinkify } from '@proton/shared/lib/mail/transformLinkify';

import { Base64Cache } from '../../hooks/useBase64Cache';
import {
    LoadEmbeddedResults,
    MessageImage,
    MessageRemoteImage,
    MessageState,
} from '../../logic/messages/messagesTypes';
import { transformBase } from './transformBase';
import { transformEmbedded } from './transformEmbedded';
import { attachBase64, transformEscape } from './transformEscape';
import { transformLinks } from './transformLinks';
import { transformRemote } from './transformRemote';
import { transformStyleAttributes } from './transformStyleAttributes';
import { transformStylesheet } from './transformStylesheet';
import { transformWelcome } from './transformWelcome';

export interface Preparation {
    plainText?: string;
    document?: Element;
    showEmbeddedImages?: boolean;
    showRemoteImages?: boolean;
    hasRemoteImages?: boolean;
    hasEmbeddedImages?: boolean;
    remoteImages?: MessageImage[];
    embeddedImages?: MessageImage[];
}

export const prepareHtml = async (
    message: MessageState,
    base64Cache: Base64Cache,
    mailSettings: MailSettings | undefined,
    onLoadEmbeddedImages: (attachments: Attachment[]) => Promise<LoadEmbeddedResults>,
    onLoadRemoteImagesProxy: (imagesToLoad: MessageRemoteImage[]) => void,
    onLoadFakeImagesProxy: (imagesToLoad: MessageRemoteImage[], firstLoad?: boolean) => void,
    onLoadRemoteImagesDirect: (imagesToLoad: MessageRemoteImage[]) => void
): Promise<Preparation> => {
    const document = transformEscape(message.decryption?.decryptedBody, base64Cache);

    transformBase(document);

    transformLinks(document);

    const { showEmbeddedImages, hasEmbeddedImages, embeddedImages } = await transformEmbedded(
        { ...message, messageDocument: { document } },
        mailSettings,
        onLoadEmbeddedImages
    );

    transformWelcome(document);

    transformStylesheet(document);

    transformStyleAttributes(document);

    const { showRemoteImages, hasRemoteImages, remoteImages } = transformRemote(
        { ...message, messageDocument: { document } },
        mailSettings,
        onLoadRemoteImagesDirect,
        onLoadRemoteImagesProxy,
        onLoadFakeImagesProxy
    );

    attachBase64(document, base64Cache);

    return {
        document,
        showRemoteImages,
        showEmbeddedImages,
        hasRemoteImages,
        remoteImages,
        hasEmbeddedImages,
        embeddedImages,
    };
};

export const preparePlainText = async (body: string, isDraft: boolean): Promise<Preparation> => {
    const plainText = isDraft ? body : transformLinkify(body);

    return { plainText };
};

import { transformStyleAttributes } from '../transformStyleAttributes';

describe('transformStyleAttributes', () => {
    it('replaces viewport heights on the root and descendants without changing other styles', () => {
        const root = document.createElement('div');
        root.setAttribute('style', 'height: 100vh; color: red');
        root.innerHTML = `
            <section style="height: calc(50vh + 10px) !important; background: proton-url(https://example.com/a.png)">
                <div style="height: 20px; min-height: 25vh; width: 30vh"></div>
            </section>
        `;

        transformStyleAttributes(root);

        const section = root.querySelector('section') as HTMLElement;
        const child = root.querySelector('section div') as HTMLElement;

        expect(root.style.height).toBe('auto');
        expect(root.style.color).toBe('red');
        expect(section.style.height).toBe('auto');
        expect(section.style.getPropertyPriority('height')).toBe('important');
        expect(section.getAttribute('style')).toContain('proton-url');
        expect(child.style.height).toBe('20px');
        expect(child.style.minHeight).toBe('25vh');
        expect(child.style.width).toBe('30vh');
    });

    it('does not treat semicolons inside other values as declaration boundaries', () => {
        const root = document.createElement('div');
        root.setAttribute(
            'style',
            'background: proton-url("https://example.com/a;v=1"); height: 40VH; content: ";height: 60vh"'
        );

        transformStyleAttributes(root);

        expect(root.getAttribute('style')).toBe(
            'background: proton-url("https://example.com/a;v=1"); height: auto; content: ";height: 60vh"'
        );
    });
});
